// === Tab: mySketch ===
/*
	generating a grid with randomly merged cells.
	Cells are randomly merged horizontaly or vertically.

	Interactions
   - LMB regenerates; R regenerate; 
   - S save; 
*/

let COLS = 10;
let ROWS = 8;
let BG = 212;

const MERGE_PROB = 0.55;
const MAX_MERGE = 3;
const BORDER = 6;
const MIN_CELL = 125; // minimum base cell size

let cellW, cellH;
let enclosures = [];
let globalSeed = 123456789; // changes on regenerate

// palettes
const TYPES = [
  {name: "zebra", clrs: ["#000000", "#FFFFFF"]},
  {name: "tiger", clrs: ["#F28C28", "#5C3A21", "#000000"]},
  {name: "leopard", clrs: ["#E1A95F", "#3C2F1B", "#000000"]},
  {name: "panda", clrs: ["#FFFFFF", "#000000"]},
  {name: "giraffe", clrs: ["#D2B48C", "#8B4513", "#C9A574"]},
  {name: "flamingo", clrs: ["#FF9AA2", "#FFCBA4"]},
  {name: "toucan", clrs: ["#000000", "#FFD700", "#FF6600"]},
  {name: "whale", clrs: ["#0E2A47", "#174C83", "#5DA8FF", "#E6F4FF"]},
  {name: "clownfish", clrs: ["#FF7F00", "#FFFFFF", "#000000"]},
  {name: "orca", clrs: ["#040410", "#FFFFFF"]}
];

function setup() {
  createCanvas(windowWidth, windowHeight);
  // // noLoop() removed for animation
}

// Interactions
function mousePressed() {
  if (mouseButton === LEFT) {
    redraw();
  }
}

function keyPressed() {
  if (key === ' ' || key === 'r' || key === 'R') {
    redraw();
  }
  if (key === 's' || key === 'S') {
    saveCanvas('epi_gradient_wang', 'png');
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
	redraw()
}

// --- choose COLS/ROWS to make cellW ≈ cellH, with min 75px constraint ---
function chooseGridForSquareCells() {
  const maxCols = floor(width / MIN_CELL);
  const minCols = max(1, min(4, maxCols)); // keep a reasonable lower bound
  if (maxCols < 1) { COLS = 1; ROWS = 1; return; }

  let best = {cols: 10, rows: 8, score: 1e9};
  const aspect = width / height;

  for (let cols = minCols; cols <= max(4, maxCols); cols++) {
    let rows = max(1, round(cols / aspect));
    // enforce min size on rows as well
    if (height / rows < MIN_CELL) continue;
    if (width / cols < MIN_CELL) continue;

    let cw = width / cols;
    let ch = height / rows;
    let diff = abs(cw - ch);

    // prefer a moderate number of total cells (optional, gentle)
    const cells = cols * rows;
    const densityPenalty = (cells < 30 || cells > 260) ? 0.15 : 0;

    let score = diff + densityPenalty;
    if (score < best.score) best = {cols, rows, score};
  }

  COLS = best.cols;
  ROWS = best.rows;
}

function calcCellSize(){
  cellW = width / COLS;
  cellH = height / ROWS;
}

function regenerate(){
  globalSeed = floor(random(1e9));
  randomSeed(globalSeed);
  noiseSeed(globalSeed);
  enclosures = buildMergedGrid();
  assignTypes();
}

function draw() {
	// console.log(frameCount + " " + millis());
	chooseGridForSquareCells();
  calcCellSize();
  regenerate();

	background(BG);
	stroke(160);

	let spacing = 10
	for (let i = 0; i < width + height; i += spacing) {
		line(i, 0, i - height, height);
	}

	for (let e of enclosures) drawEnclosure(e);

	// noLoop() removed for animation // static
}



// --- Grid merging ---
function buildMergedGrid(){
  let used = Array(ROWS).fill().map(()=>Array(COLS).fill(false));
  let list = [];

  for (let gy=0; gy<ROWS; gy++){
    for (let gx=0; gx<COLS; gx++){
      if (used[gy][gx]) continue;

      let gW = 1, gH = 1;
      let tryHorizontalFirst = random() < 0.5;

      if (random() < MERGE_PROB) {
        if (tryHorizontalFirst) {
          gW = min(COLS - gx, 1 + floor(random(MAX_MERGE)));
          while (!fits(used, gx, gy, gW, 1) && gW > 1) gW--;
          if (random() < 0.45) {
            gH = min(ROWS - gy, 1 + floor(random(min(MAX_MERGE, 3))));
            while (!fits(used, gx, gy, gW, gH) && gH > 1) gH--;
          }
        } else {
          gH = min(ROWS - gy, 1 + floor(random(MAX_MERGE)));
          while (!fits(used, gx, gy, 1, gH) && gH > 1) gH--;
          if (random() < 0.45) {
            gW = min(COLS - gx, 1 + floor(random(min(MAX_MERGE, 3))));
            while (!fits(used, gx, gy, gW, gH) && gW > 1) gW--;
          }
        }
      }

      mark(used, gx, gy, gW, gH);
      let px = gx * cellW, py = gy * cellH, w = gW * cellW, h = gH * cellH;
      let kind = classifyAspect(w / h);
      list.push({gx, gy, gW, gH, px, py, w, h, kind, animal: null});
    }
  }
  return list;
}

function fits(used, gx, gy, gW, gH){
  if (gx+gW > COLS || gy+gH > ROWS) return false;
  for (let y=gy; y<gy+gH; y++){
    for (let x=gx; x<gx+gW; x++){
      if (used[y][x]) return false;
    }
  }
  return true;
}
function mark(used, gx, gy, gW, gH){
  for (let y=gy; y<gy+gH; y++){
    for (let x=gx; x<gx+gW; x++){
      used[y][x] = true;
    }
  }
}
function classifyAspect(aspect){
  if (aspect > 1.25) return "horizontal";
  if (aspect < 0.8)  return "vertical";
  return "square";
}

// --- Type assignment ---
function assignTypes(){
  for (let e of enclosures) {
		e.type = ~~random(TYPES.length);
  }
}


// --- Drawing ---

function drawEnclosure(e){
	// console.log(ANIMALS[e.animal])

	push();
  translate(~~e.px, ~~e.py);
  noStroke();
  const x = BORDER, y = BORDER, w = e.w - 2*BORDER, h = e.h - 2*BORDER;

	let r = min(w, h) / 2.25;
	let edges = [1*r, 1*r, 1*r, 1*r];
	for (let i = 0; i < 2; i++) {
		const idx = ~~random(edges.length)
		edges[idx] = 0;
	}

	// clrs
	const clrs = TYPES[e.type].clrs;
	shuffle(clrs, true);
	fill(clrs[0]);
	stroke(32); strokeWeight(r/5);

	// gradient fill + stroke seperate 

	const ctx = drawingContext;
	const gradFill = ctx.createLinearGradient(x, y, x, y+h);
	for (let i = 0; i < clrs.length; i++) {
		const f = i/(clrs.length-1);
		gradFill.addColorStop(f, clrs[i]);
	} 
	ctx.fillStyle = gradFill;

	if (random()<0.5) shuffle(clrs, true);
	const gradStroke = ctx.createLinearGradient(x, y, x, y+h);
	for (let i = clrs.length-1; i >= 0; i--) {
		var f = 1 - i/(clrs.length-1);
		gradStroke.addColorStop(f, clrs[i]);
	} 
	ctx.strokeStyle = gradStroke;
	noStroke()

	rect(x, y, w, h, ...edges);

  pop();
}


